{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_f0ea7b65d21dd461bcb74b8b", "claim_ids": ["claim_34151d0d22bacb19e43b4c38", "claim_ce51c8abeeeec079cae18327"], "query_ids": ["q_119"], "claims": [{"claim_id": "claim_34151d0d22bacb19e43b4c38", "quote": "CBP has previously held that the assembly of battery cells into battery packs does not result in a substantial transformation", "url": "https://www.customsmobile.com/rulings/docview?doc_id=HQ+H316545&highlight=HQ+H316545", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "CBP"}}, {"claim_id": "claim_ce51c8abeeeec079cae18327", "quote": "Both the battery modules and battery packs are assembled in Canada through multi-step assembly processes that include: applying adhesive, aligning, pressing, curing, plasma cleaning, laser ablation, wire bonding, material", "url": "https://www.cmtradelaw.com/2023/01/customs-ruling-of-the-week-country-of-origin-of-battery-modules-and-battery-packs-and-the-applicability-of-certain-trade-remedies-under-section-301", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_3bed5bec0559634f484952ed", "claim_ids": ["claim_4715c0403ceaec4aec5004a8", "claim_a0a1474a00d3dbcfaeb2bd87"], "query_ids": ["q_12"], "claims": [{"claim_id": "claim_4715c0403ceaec4aec5004a8", "quote": "General Motors (GM.N) said it will face up to $5 billion in gross tariff-related costs this year", "url": "https://www.reuters.com/business/media-telecom/automakers-have-resisted-raising-car-prices-because-tariffs-that-might-not-last-2025-09-18", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "General Motors (GM.N)", "tariff_program": "tariff-related costs", "duty_rate": "$5 billion"}}, {"claim_id": "claim_a0a1474a00d3dbcfaeb2bd87", "quote": "General Motors reported that it had absorbed $1.1 billion in tariff costs last quarter but prioritized maintaining imports to support customers and dealers.", "url": "https://www.coxautoinc.com/insights-hub/the-trump-tariff-stance-has-shifted-where-are-we-now", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "General Motors", "duty_rate": "$1.1 billion", "reported_policy_status": "absorbed"}}]}, {"pair_id": "conflict_06d358de74b3e1ed7ab1ef3b", "claim_ids": ["claim_986192c016bd36c03d2609fc", "claim_da11a29346cbc00ec5115cf4"], "query_ids": ["q_122"], "claims": [{"claim_id": "claim_986192c016bd36c03d2609fc", "quote": "A 93.5 percent tariff on Chinese graphite – the primary anode material in virtually all lithium-ion batteries – took effect, representing one of the most significant raw material tariffs in US manufacturing history.", "url": "https://www.totexmfg.com/battery-pack-tariffs-oem-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Totex Manufacturing", "tariff_program": "Section 301 tariffs on Chinese battery products", "affected_product": "Chinese graphite", "duty_rate": "93.5 percent", "effective_date": "January 2025"}}, {"claim_id": "claim_da11a29346cbc00ec5115cf4", "quote": "The Commerce Department plans to impose a 93.5 percent levy on Chinese graphite, an essential ingredient in the batteries that power electric", "url": "https://www.nytimes.com/2025/07/17/business/trump-graphite-tariff-electric-vehicles.html", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Commerce Department", "tariff_program": "93.5 percent levy", "affected_product": "Chinese graphite", "duty_rate": "93.5 percent", "reported_policy_status": "plans to impose"}}]}, {"pair_id": "conflict_9dc86166b020793d88f96bae", "claim_ids": ["claim_986192c016bd36c03d2609fc", "claim_b1e785342c7d06a52038496d"], "query_ids": ["q_122"], "claims": [{"claim_id": "claim_986192c016bd36c03d2609fc", "quote": "A 93.5 percent tariff on Chinese graphite – the primary anode material in virtually all lithium-ion batteries – took effect, representing one of the most significant raw material tariffs in US manufacturing history.", "url": "https://www.totexmfg.com/battery-pack-tariffs-oem-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Totex Manufacturing", "tariff_program": "Section 301 tariffs on Chinese battery products", "affected_product": "Chinese graphite", "duty_rate": "93.5 percent", "effective_date": "January 2025"}}, {"claim_id": "claim_b1e785342c7d06a52038496d", "quote": "The US Department of Commerce has provisionally decided to impose anti-dumping (AD) tariffs on active anode material (AAM) product imports from China of 93.5%, bringing the total tariff on them to 160%.", "url": "https://www.energy-storage.news/us-imposes-93-5-tariff-on-chinese-battery-anode-products-but-bess-spared", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "US Department of Commerce", "tariff_program": "anti-dumping (AD)", "affected_product": "active anode material (AAM) product", "duty_rate": "93.5%", "reported_policy_status": "provisionally decided"}}]}, {"pair_id": "conflict_0cdece981790ed06e4938103", "claim_ids": ["claim_7bc403bf66ff8e9d400a1f09", "claim_d542b4df559832603f5b3d62"], "query_ids": ["q_126"], "claims": [{"claim_id": "claim_7bc403bf66ff8e9d400a1f09", "quote": "Natural graphite | 0% | 25% | Jan 1, 2026", "url": "https://ustariffrates.com/section-301-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301 tariffs", "affected_product": "Natural graphite", "country_of_origin": "China", "duty_rate": "25%", "effective_date": "Jan 1, 2026"}}, {"claim_id": "claim_d542b4df559832603f5b3d62", "quote": "NOVONIX Limited (NASDAQ: NVX, ASX: NVX) (“NOVONIX”), a leading battery materials and technology company, today applauded the recent announcement by the United States Trade Representative (USTR) on Section 301 tariffs, removing the current exclusions and reimposing the 25% tariff on artificial graphite and natural graphite powder imported from China effective June 15, 2024.", "url": "https://www.novonixgroup.com/news/united-states-government-to-reinstate-section-301-import-tariffs-on-artificial-graphite-from-china", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "NOVONIX Limited", "legal_authority": "United States Trade Representative (USTR)", "affected_product": "artificial graphite and natural graphite powder", "duty_rate": "25%", "effective_date": "June 15, 2024"}}]}, {"pair_id": "conflict_5700f64b3885d84b0a175968", "claim_ids": ["claim_54569a9f9c3187ea4f1ea135", "claim_affa707db57513b0e3796a3a"], "query_ids": ["q_127"], "claims": [{"claim_id": "claim_54569a9f9c3187ea4f1ea135", "quote": "The graphite industry in 2025 faces major challenges, including trade wars, high US tariffs on synthetic graphite and policy changes affecting EV manufacturing and tax credits.", "url": "https://www.fastmarkets.com/insights/navigating-china-graphite-import-tariffs", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "US tariffs on synthetic graphite", "affected_product": "synthetic graphite"}}, {"claim_id": "claim_affa707db57513b0e3796a3a", "quote": "Until August 12, when the 90-day pause ends, US import tariffs on Chinese synthetic graphite will stand at 55%. This comprises the 25% Section 301 tariff, the 20% IEEPA tariffs, and the 10% universal tariff.", "url": "https://www.fastmarkets.com/insights/navigating-china-graphite-import-tariffs", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "US", "affected_product": "synthetic graphite", "duty_rate": "55%", "effective_date": "Until August 12"}}]}, {"pair_id": "conflict_8c0e7de816012547f8d880a1", "claim_ids": ["claim_019b33cc19520d531d58ee0f", "claim_33cc8973ec8f9b96af11498a"], "query_ids": ["q_13"], "claims": [{"claim_id": "claim_019b33cc19520d531d58ee0f", "quote": "in addition to the 25% product tariffs already imposed on cars, car parts, steel, and aluminum.", "url": "https://www.iebrain.com/mediacoverage/automotive-supply-chain-localization-transformative-step-amid-tariff-wars", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "product tariffs", "duty_rate": "25%"}}, {"claim_id": "claim_33cc8973ec8f9b96af11498a", "quote": "Nearly all the US's trading partners are now subject to a 10% base tariff, in addition to the 25% product tariffs already imposed on cars, car parts, steel, and aluminum.", "url": "https://www.autocarpro.in/opinion-column/automotive-supply-chain-localization-transformative-step-amid-tariff-wars-126555", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "product tariffs", "duty_rate": "25%"}}]}, {"pair_id": "conflict_5fbb2b491a308f06ac90c32b", "claim_ids": ["claim_49c30a5467fc7f46a917bd9d", "claim_fcff30c0a699f697487c67b5"], "query_ids": ["q_13"], "claims": [{"claim_id": "claim_49c30a5467fc7f46a917bd9d", "quote": "The US Administration has instituted a 90-day pause on its broad-based global tariffs, but this temporary relief does not apply to China; Nearly all the US's trading partners are now subject to a 10% base tariff", "url": "https://www.iebrain.com/mediacoverage/automotive-supply-chain-localization-transformative-step-amid-tariff-wars", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "broad-based global tariffs", "duty_rate": "10%"}}, {"claim_id": "claim_fcff30c0a699f697487c67b5", "quote": "The US Administration has instituted a 90-day pause on its broad-based global tariffs, but this temporary relief does not apply to China; Nearly all the US's trading partners are now subject to a 10% base tariff", "url": "https://www.autocarpro.in/opinion-column/automotive-supply-chain-localization-transformative-step-amid-tariff-wars-126555", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "broad-based global tariffs", "duty_rate": "10%"}}]}, {"pair_id": "conflict_b82344b603d6abf54e7412d6", "claim_ids": ["claim_c0a17657e7fdba3435141fb1", "claim_cdfc61f4a4e6c398f9bbe07e"], "query_ids": ["q_13"], "claims": [{"claim_id": "claim_c0a17657e7fdba3435141fb1", "quote": "Ford has invested more than USD 7 billion in AI-powered manufacturing to utilize machine learning to enhance battery production for electric vehicles (EVs)", "url": "https://www.autocarpro.in/opinion-column/automotive-supply-chain-localization-transformative-step-amid-tariff-wars-126555", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Ford"}}, {"claim_id": "claim_cdfc61f4a4e6c398f9bbe07e", "quote": "Ford has invested more than USD 7 billion in AI-powered manufacturing to utilize machine learning to enhance battery production for electric vehicles (EVs)", "url": "https://www.iebrain.com/mediacoverage/automotive-supply-chain-localization-transformative-step-amid-tariff-wars", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Ford"}}]}, {"pair_id": "conflict_805c31b4a186a4f1dbf663ea", "claim_ids": ["claim_4eb9995315f0524c678e0209", "claim_e5edc106ac926a07fcf7931e"], "query_ids": ["q_13"], "claims": [{"claim_id": "claim_4eb9995315f0524c678e0209", "quote": "Toyota has opened a new automotive battery plant in North Carolina, with a USD 14 billion investment company plans to start battery production for North American electrified vehicles.", "url": "https://www.iebrain.com/mediacoverage/automotive-supply-chain-localization-transformative-step-amid-tariff-wars", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Toyota", "facility": "automotive battery plant"}}, {"claim_id": "claim_e5edc106ac926a07fcf7931e", "quote": "Toyota has opened a new automotive battery plant in North Carolina, with a USD 14 billion investment company plans to start battery production for North American electrified vehicles.", "url": "https://www.autocarpro.in/opinion-column/automotive-supply-chain-localization-transformative-step-amid-tariff-wars-126555", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Toyota", "facility": "automotive battery plant"}}]}]}

